(7450276, 1179034, 96751, '<td valign="top">Nicely done. Looks like a school prank gone wrong :)</td>', 'Nicely done. Looks like a school prank gone wrong :)', '2016-04-14 20:37:06.000000', NULL, 1),
(7450277, 1179059, 103142, '<td valign="top">I love the title on this one. It makes you wonder about a story behind it, even though I knew it was just a collection of challenge items. The title made me forget for awhile and started looking deeper. :) (already voted)</td>', 'I love the title on this one. It makes you wonder about a story behind it, even though I knew it was just a collection of challenge items. The title made me forget for awhile and started looking deeper. :) (already voted)', '2016-04-14 20:38:12.000000', NULL, 1),
